-- Stage 7: temporary contextual location coordination. Apply after 0011_social_coordination.sql.
alter table public.location_sharing_sessions add column if not exists context_kind text;
alter table public.location_sharing_sessions add column if not exists event_id uuid references public.events(id) on delete cascade;
alter table public.location_sharing_sessions add column if not exists plan_id uuid references public.plans(id) on delete cascade;
alter table public.location_sharing_sessions add column if not exists conversation_id uuid references public.conversations(id) on delete cascade;
alter table public.location_sharing_sessions add column if not exists duration_kind text;
alter table public.location_sharing_sessions add column if not exists confirmed_at timestamptz;
alter table public.location_sharing_sessions add column if not exists last_point_at timestamptz;
alter table public.location_sharing_sessions add column if not exists last_reminder_at timestamptz;
alter table public.location_sharing_sessions add column if not exists stopped_reason text;
alter table public.location_sharing_sessions add column if not exists retention_until timestamptz;
alter table public.location_sharing_sessions drop constraint if exists location_sharing_sessions_purpose_check;
alter table public.location_sharing_sessions add constraint location_sharing_sessions_purpose_check check(purpose in('event','journey','meetup','plan','conversation'));
alter table public.location_sharing_sessions drop constraint if exists location_sharing_sessions_precision_check;
alter table public.location_sharing_sessions add constraint location_sharing_sessions_precision_check check(precision in('approximate','venue','precise'));
alter table public.location_sharing_sessions drop constraint if exists valid_location_window;
alter table public.location_sharing_sessions add constraint valid_location_window check(expires_at>starts_at and expires_at<=starts_at+interval '24 hours');
do $$begin if not exists(select 1 from pg_constraint where conname='location_sharing_context_check')then alter table public.location_sharing_sessions add constraint location_sharing_context_check check(context_kind in('event','plan','conversation')and num_nonnulls(event_id,plan_id,conversation_id)=1);end if;if not exists(select 1 from pg_constraint where conname='location_sharing_duration_check')then alter table public.location_sharing_sessions add constraint location_sharing_duration_check check(duration_kind in('15m','1h','journey','event_end'));end if;end$$;
update public.location_sharing_sessions set stopped_at=coalesce(stopped_at,now()),stopped_reason='legacy_context_retired',retention_until=now()+interval '24 hours'where context_kind is null;delete from public.ephemeral_location_points;drop policy if exists "location owners manage sessions" on public.location_sharing_sessions;drop policy if exists "authorized location points" on public.ephemeral_location_points;revoke all on public.ephemeral_location_points from anon,authenticated;
alter table public.location_session_viewers add column if not exists selected_at timestamptz not null default now();alter table public.location_session_viewers add column if not exists revoked_at timestamptz;alter table public.location_session_viewers add column if not exists revoke_reason text;
create table if not exists public.location_current_points(session_id uuid primary key references public.location_sharing_sessions(id) on delete cascade,owner_id uuid not null references public.profiles(id) on delete cascade,point geography(point,4326) not null,latitude double precision not null,longitude double precision not null,accuracy_m double precision,recorded_at timestamptz not null default now(),delete_after timestamptz not null);
create index if not exists location_current_points_delete_idx on public.location_current_points(delete_after);
create table if not exists public.location_viewer_snapshots(session_id uuid references public.location_sharing_sessions(id) on delete cascade,viewer_id uuid references public.profiles(id) on delete cascade,owner_id uuid references public.profiles(id) on delete cascade,precision text not null,latitude double precision,longitude double precision,accuracy_m double precision,venue_presence boolean not null default false,updated_at timestamptz not null default now(),expires_at timestamptz not null,primary key(session_id,viewer_id));
create index if not exists location_viewer_snapshots_viewer_idx on public.location_viewer_snapshots(viewer_id,expires_at);
create table if not exists public.location_access_logs(id bigint generated always as identity primary key,session_id uuid references public.location_sharing_sessions(id) on delete set null,owner_id uuid references public.profiles(id) on delete set null,actor_id uuid references public.profiles(id) on delete set null,action text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),delete_after timestamptz not null default(now()+interval '7 days'));
create table if not exists public.shared_meeting_points(id uuid primary key default gen_random_uuid(),context_kind text not null,event_id uuid references public.events(id) on delete cascade,plan_id uuid references public.plans(id) on delete cascade,conversation_id uuid references public.conversations(id) on delete cascade,created_by uuid not null references public.profiles(id) on delete cascade,label text not null,point geography(point,4326) not null,latitude double precision not null,longitude double precision not null,created_at timestamptz not null default now(),expires_at timestamptz not null,check(num_nonnulls(event_id,plan_id,conversation_id)=1));
create table if not exists public.context_arrival_statuses(context_kind text not null,context_id uuid not null,profile_id uuid references public.profiles(id) on delete cascade,status text not null,updated_at timestamptz not null default now(),expires_at timestamptz not null,primary key(context_kind,context_id,profile_id));
create or replace function public.is_minor_or_unverified(target uuid)returns boolean language sql stable security definer set search_path=public as $$select coalesce((select birth_date is null or birth_date>current_date-interval '18 years'from public.profiles where id=target),true)$$;
create or replace function public.location_context_member(person uuid,kind text,target uuid)returns boolean language sql stable security definer set search_path=public as $$select case kind when'event'then exists(select 1 from public.event_rsvps where event_id=target and profile_id=person and status in('going','checked_in'))or exists(select 1 from public.events e where e.id=target and(e.created_by=person or exists(select 1 from public.host_members h where h.host_profile_id=e.host_profile_id and h.profile_id=person and h.accepted_at is not null)))when'plan'then exists(select 1 from public.plan_members where plan_id=target and profile_id=person and status='accepted')when'conversation'then exists(select 1 from public.conversations c join public.conversation_members m on m.conversation_id=c.id where c.id=target and c.kind='direct'and m.profile_id=person and m.left_at is null)else false end$$;
create or replace function public.location_recipient_allowed(owner_profile uuid,recipient_profile uuid,kind text,target uuid)returns boolean language sql stable security definer set search_path=public as $$select owner_profile<>recipient_profile and not public.is_minor_or_unverified(owner_profile)and not public.is_minor_or_unverified(recipient_profile)and public.profiles_are_friends(owner_profile,recipient_profile)and public.location_context_member(owner_profile,kind,target)and public.location_context_member(recipient_profile,kind,target)$$;
create or replace function public.can_read_location_session(target_session uuid,person uuid default auth.uid())returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.location_sharing_sessions s where s.id=target_session and(s.owner_id=person or(s.stopped_at is null and s.expires_at>now()and exists(select 1 from public.location_session_viewers v where v.session_id=s.id and v.viewer_id=person and v.revoked_at is null)and public.location_recipient_allowed(s.owner_id,person,s.context_kind,coalesce(s.event_id,s.plan_id,s.conversation_id)))))or public.is_admin()$$;
create or replace function public.eligible_location_recipients_v1(target_kind text,target_id uuid)returns table(profile_id uuid,display_name text,username text)language sql stable security definer set search_path=public as $$with f as(select case when requester_id=auth.uid()then addressee_id else requester_id end id from public.friendships where state='accepted'and(requester_id=auth.uid()or addressee_id=auth.uid()))select p.id,p.display_name,p.username from f join public.profiles p on p.id=f.id where public.location_recipient_allowed(auth.uid(),p.id,target_kind,target_id)order by lower(p.display_name)$$;
create or replace function public.start_location_share_v1(target_kind text,target_id uuid,recipient_ids uuid[],sharing_precision text,sharing_duration text,confirmed boolean)returns jsonb language plpgsql security definer set search_path=public as $$declare actor uuid:=auth.uid();r uuid;sid uuid;expiry timestamptz;valid_count integer;begin if actor is null or not confirmed then raise exception 'confirm sharing every time';end if;if public.is_minor_or_unverified(actor)then raise exception 'live location unavailable for minors';end if;if not public.location_context_member(actor,target_kind,target_id)then raise exception 'context unavailable';end if;if sharing_precision not in('approximate','venue','precise')or sharing_duration not in('15m','1h','journey','event_end')then raise exception 'invalid sharing options';end if;if sharing_precision='venue'and target_kind<>'event'then raise exception 'venue presence requires an event';end if;if recipient_ids is null or cardinality(recipient_ids)=0 or cardinality(recipient_ids)>20 then raise exception 'choose recipients';end if;select count(distinct x)into valid_count from unnest(recipient_ids)x where public.location_recipient_allowed(actor,x,target_kind,target_id);if valid_count<>cardinality(array(select distinct x from unnest(recipient_ids)x))then raise exception 'recipient unavailable';end if;expiry:=case sharing_duration when'15m'then now()+interval '15 minutes'when'1h'then now()+interval '1 hour'when'journey'then now()+interval '8 hours'else null end;if sharing_duration='event_end'then if target_kind<>'event'then raise exception 'event duration unavailable';end if;select least(ends_at,now()+interval '24 hours')into expiry from public.events where id=target_id and ends_at>now();end if;if expiry is null then raise exception 'duration unavailable';end if;insert into public.location_sharing_sessions(owner_id,purpose,precision,starts_at,expires_at,context_kind,event_id,plan_id,conversation_id,duration_kind,confirmed_at,retention_until)values(actor,case when sharing_duration='journey'then'journey'else target_kind end,sharing_precision,now(),expiry,target_kind,case when target_kind='event'then target_id end,case when target_kind='plan'then target_id end,case when target_kind='conversation'then target_id end,sharing_duration,now(),expiry+interval '24 hours')returning id into sid;for r in select distinct x from unnest(recipient_ids)x loop insert into public.location_session_viewers(session_id,viewer_id)values(sid,r);perform public.queue_notification_v1(r,actor,'location_share','Temporary location shared','A trusted friend shared a temporary location with you.','/inbox',jsonb_build_object('session_id',sid,'expires_at',expiry));end loop;insert into public.location_access_logs(session_id,owner_id,actor_id,action,metadata)values(sid,actor,actor,'started',jsonb_build_object('precision',sharing_precision,'recipients',valid_count));return jsonb_build_object('id',sid,'expires_at',expiry);end$$;
create or replace function public.update_location_point_v1(target_session uuid,point_latitude double precision,point_longitude double precision,point_accuracy double precision default null)returns jsonb language plpgsql security definer set search_path=public as $$declare s public.location_sharing_sessions%rowtype;v uuid;lat double precision;lng double precision;presence boolean;venue geography(point,4326);begin select * into s from public.location_sharing_sessions where id=target_session and owner_id=auth.uid()for update;if s.id is null or s.stopped_at is not null or s.expires_at<=now()then raise exception 'session inactive';end if;if point_latitude not between -90 and 90 or point_longitude not between -180 and 180 then raise exception 'invalid coordinate';end if;insert into public.location_current_points values(s.id,s.owner_id,st_setsrid(st_makepoint(point_longitude,point_latitude),4326)::geography,point_latitude,point_longitude,least(greatest(coalesce(point_accuracy,0),0),100000),now(),least(s.expires_at,now()+interval '10 minutes'))on conflict(session_id)do update set point=excluded.point,latitude=excluded.latitude,longitude=excluded.longitude,accuracy_m=excluded.accuracy_m,recorded_at=excluded.recorded_at,delete_after=excluded.delete_after;update public.location_sharing_sessions set last_point_at=now()where id=s.id;for v in select viewer_id from public.location_session_viewers where session_id=s.id and revoked_at is null loop if s.precision='precise'then lat:=point_latitude;lng:=point_longitude;presence:=false;elsif s.precision='approximate'then lat:=round(point_latitude::numeric,2);lng:=round(point_longitude::numeric,2);presence:=false;else select l.point into venue from public.events e join public.locations l on l.id=e.location_id where e.id=s.event_id;if venue is null then raise exception 'venue unavailable';end if;lat:=null;lng:=null;presence:=st_dwithin(st_setsrid(st_makepoint(point_longitude,point_latitude),4326)::geography,venue,250);end if;insert into public.location_viewer_snapshots values(s.id,v,s.owner_id,s.precision,lat,lng,case when s.precision='precise'then point_accuracy end,presence,now(),s.expires_at)on conflict(session_id,viewer_id)do update set precision=excluded.precision,latitude=excluded.latitude,longitude=excluded.longitude,accuracy_m=excluded.accuracy_m,venue_presence=excluded.venue_presence,updated_at=excluded.updated_at,expires_at=excluded.expires_at;end loop;return jsonb_build_object('updated_at',now(),'expires_at',s.expires_at);end$$;
create or replace function public.stop_location_share_v1(target_session uuid,reason text default'owner_stopped')returns boolean language plpgsql security definer set search_path=public as $$declare s public.location_sharing_sessions%rowtype;begin select * into s from public.location_sharing_sessions where id=target_session for update;if s.id is null or(s.owner_id<>auth.uid()and not public.is_admin())then raise exception 'session unavailable';end if;update public.location_sharing_sessions set stopped_at=coalesce(stopped_at,now()),stopped_reason=left(reason,80),retention_until=now()+interval '24 hours'where id=s.id;delete from public.location_current_points where session_id=s.id;delete from public.location_viewer_snapshots where session_id=s.id;insert into public.location_access_logs(session_id,owner_id,actor_id,action,metadata)values(s.id,s.owner_id,auth.uid(),'stopped',jsonb_build_object('reason',reason));return true;end$$;
create or replace function public.view_location_share_v1(target_session uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare s public.location_sharing_sessions%rowtype;x public.location_viewer_snapshots%rowtype;n text;begin select * into s from public.location_sharing_sessions where id=target_session;if s.id is null or s.stopped_at is not null or s.expires_at<=now()then raise exception 'session inactive';end if;select display_name into n from public.profiles where id=s.owner_id;if auth.uid()=s.owner_id then return jsonb_build_object('id',s.id,'owner_id',s.owner_id,'owner_name',n,'precision',s.precision,'expires_at',s.expires_at,'is_owner',true);end if;if not public.can_read_location_session(s.id)then raise exception 'not authorized';end if;select * into x from public.location_viewer_snapshots where session_id=s.id and viewer_id=auth.uid()and expires_at>now();if x.session_id is null then raise exception 'location not available yet';end if;if not exists(select 1 from public.location_access_logs where session_id=s.id and actor_id=auth.uid()and action='viewed'and created_at>now()-interval '1 minute')then insert into public.location_access_logs(session_id,owner_id,actor_id,action)values(s.id,s.owner_id,auth.uid(),'viewed');end if;return jsonb_build_object('id',s.id,'owner_id',s.owner_id,'owner_name',n,'precision',x.precision,'latitude',x.latitude,'longitude',x.longitude,'accuracy_m',x.accuracy_m,'venue_presence',x.venue_presence,'updated_at',x.updated_at,'expires_at',s.expires_at);end$$;
create or replace function public.set_shared_meeting_point_v1(target_kind text,target_id uuid,point_label text,point_latitude double precision,point_longitude double precision)returns uuid language plpgsql security definer set search_path=public as $$declare mid uuid;expiry timestamptz:=now()+interval '8 hours';begin if not public.location_context_member(auth.uid(),target_kind,target_id)then raise exception 'context unavailable';end if;if target_kind='event'then select least(ends_at+interval '2 hours',now()+interval '24 hours')into expiry from public.events where id=target_id;elsif target_kind='plan'then select least(coalesce(ends_at,now()+interval '8 hours')+interval '2 hours',now()+interval '24 hours')into expiry from public.plans where id=target_id;end if;insert into public.shared_meeting_points(context_kind,event_id,plan_id,conversation_id,created_by,label,point,latitude,longitude,expires_at)values(target_kind,case when target_kind='event'then target_id end,case when target_kind='plan'then target_id end,case when target_kind='conversation'then target_id end,auth.uid(),left(trim(point_label),160),st_setsrid(st_makepoint(point_longitude,point_latitude),4326)::geography,point_latitude,point_longitude,expiry)returning id into mid;return mid;end$$;
create or replace function public.set_arrival_status_v1(target_kind text,target_id uuid,arrival_state text)returns text language plpgsql security definer set search_path=public as $$begin if not public.location_context_member(auth.uid(),target_kind,target_id)or arrival_state not in('heading_there','arrived','left')then raise exception 'status unavailable';end if;insert into public.context_arrival_statuses values(target_kind,target_id,auth.uid(),arrival_state,now(),now()+interval '8 hours')on conflict(context_kind,context_id,profile_id)do update set status=excluded.status,updated_at=excluded.updated_at,expires_at=excluded.expires_at;return arrival_state;end$$;
create or replace function public.expire_location_shares_v1(batch_size integer default 250)returns jsonb language plpgsql security definer set search_path=public as $$declare s public.location_sharing_sessions%rowtype;n integer:=0;begin for s in select * from public.location_sharing_sessions where stopped_at is null and expires_at<=now()order by expires_at limit greatest(1,least(batch_size,1000))for update skip locked loop update public.location_sharing_sessions set stopped_at=now(),stopped_reason='expired',retention_until=now()+interval '24 hours'where id=s.id;delete from public.location_current_points where session_id=s.id;delete from public.location_viewer_snapshots where session_id=s.id;insert into public.location_access_logs(session_id,owner_id,action)values(s.id,s.owner_id,'expired');n:=n+1;end loop;delete from public.location_current_points where delete_after<=now();delete from public.location_viewer_snapshots where expires_at<=now();delete from public.shared_meeting_points where expires_at<=now();delete from public.context_arrival_statuses where expires_at<=now();delete from public.location_access_logs where delete_after<=now();delete from public.location_sharing_sessions where stopped_at is not null and coalesce(retention_until,stopped_at+interval '24 hours')<=now();for s in select * from public.location_sharing_sessions where stopped_at is null and expires_at>now()+interval '5 minutes'and now()-starts_at>=interval '30 minutes'and(last_reminder_at is null or last_reminder_at<now()-interval '30 minutes')limit greatest(1,least(batch_size,1000))for update skip locked loop perform public.queue_notification_v1(s.owner_id,null,'location_reminder','Location sharing is still active','Your temporary location is still being shared.','/inbox',jsonb_build_object('session_id',s.id));update public.location_sharing_sessions set last_reminder_at=now()where id=s.id;end loop;return jsonb_build_object('expired',n);end$$;
create or replace function public.revoke_location_sharing_on_block()returns trigger language plpgsql security definer set search_path=public as $$declare sid uuid;own uuid;begin for sid,own in select s.id,s.owner_id from public.location_sharing_sessions s join public.location_session_viewers v on v.session_id=s.id where s.stopped_at is null and((s.owner_id=new.blocker_id and v.viewer_id=new.blocked_id)or(s.owner_id=new.blocked_id and v.viewer_id=new.blocker_id))loop update public.location_session_viewers set revoked_at=now(),revoke_reason='blocked'where session_id=sid and viewer_id in(new.blocker_id,new.blocked_id);delete from public.location_viewer_snapshots where session_id=sid and viewer_id in(new.blocker_id,new.blocked_id);if not exists(select 1 from public.location_session_viewers where session_id=sid and revoked_at is null)then update public.location_sharing_sessions set stopped_at=now(),stopped_reason='all_recipients_revoked',retention_until=now()+interval '24 hours'where id=sid;delete from public.location_current_points where session_id=sid;end if;end loop;return new;end$$;
drop trigger if exists blocks_revoke_location_sharing on public.blocks;create trigger blocks_revoke_location_sharing after insert on public.blocks for each row execute function public.revoke_location_sharing_on_block();
alter table public.location_sharing_sessions enable row level security;alter table public.location_session_viewers enable row level security;alter table public.location_current_points enable row level security;alter table public.location_viewer_snapshots enable row level security;alter table public.location_access_logs enable row level security;alter table public.shared_meeting_points enable row level security;alter table public.context_arrival_statuses enable row level security;
drop policy if exists "location owners and viewers read sessions" on public.location_sharing_sessions;create policy "location owners and viewers read sessions" on public.location_sharing_sessions for select using(public.can_read_location_session(id));create policy "location participants read viewer selection" on public.location_session_viewers for select using(public.can_read_location_session(session_id));create policy "owners read own current point" on public.location_current_points for select using(owner_id=auth.uid()or public.is_admin());create policy "viewers read sanitized current snapshots" on public.location_viewer_snapshots for select using(owner_id=auth.uid()or(viewer_id=auth.uid()and expires_at>now()and public.can_read_location_session(session_id))or public.is_admin());create policy "owners read location access log" on public.location_access_logs for select using(owner_id=auth.uid()or actor_id=auth.uid()or public.is_admin());create policy "context members read meeting points" on public.shared_meeting_points for select using(expires_at>now()and public.location_context_member(auth.uid(),context_kind,coalesce(event_id,plan_id,conversation_id))or public.is_admin());create policy "context members read arrival statuses" on public.context_arrival_statuses for select using(expires_at>now()and public.location_context_member(auth.uid(),context_kind,context_id)or public.is_admin());
revoke insert,update,delete on public.location_sharing_sessions,public.location_session_viewers,public.location_current_points,public.location_viewer_snapshots,public.location_access_logs,public.shared_meeting_points,public.context_arrival_statuses from authenticated;
do $$begin begin alter publication supabase_realtime add table public.location_sharing_sessions;exception when duplicate_object then null;end;begin alter publication supabase_realtime add table public.location_viewer_snapshots;exception when duplicate_object then null;end;begin alter publication supabase_realtime add table public.shared_meeting_points;exception when duplicate_object then null;end;begin alter publication supabase_realtime add table public.context_arrival_statuses;exception when duplicate_object then null;end;end$$;
grant execute on function public.eligible_location_recipients_v1(text,uuid),public.start_location_share_v1(text,uuid,uuid[],text,text,boolean),public.update_location_point_v1(uuid,double precision,double precision,double precision),public.stop_location_share_v1(uuid,text),public.view_location_share_v1(uuid),public.set_shared_meeting_point_v1(text,uuid,text,double precision,double precision),public.set_arrival_status_v1(text,uuid,text)to authenticated;revoke execute on function public.expire_location_shares_v1(integer)from public,anon,authenticated;
